export default {
  contribute() {
    return {
      uiSlots: [
        {
          id: "counter-detail",
          slot: "task.detail",
          title: "计数",
          fields: [{ key: "count", label: "计数" }],
          actions: [{ commandId: "incrementCount", label: "计数+1" }]
        }
      ],
      fields: [{ key: "count", label: "计数", type: "text" }],
      commands: [{ id: "incrementCount", label: "计数+1", from: ["open"] }]
    };
  },
  decide({ task, action, input }) {
    if (action !== "incrementCount") {
      return { kind: "reject", message: "未知动作" };
    }
    if (task.state !== "open") {
      return { kind: "reject", message: "只能在未完成状态下递增计数" };
    }
    const currentCount = parseInt(task.fields.count || "0", 10);
    const newCount = isNaN(currentCount) ? 1 : currentCount + 1;
    return {
      kind: "commit",
      state: task.state,
      fields: { ...task.fields, count: String(newCount) }
    };
  }
};

